items.solution:
function checkMonotonic(fn, maxInput, step) {
  let prev = fn(0);
  for (let x = step; x <= maxInput; x += step) {
    const cur = fn(x);
    if (cur < prev) return { violated: true, at: x, prev, cur };
    prev = cur;
  }
  return { violated: false };
}

